      "审核时怎么问": "一、岗位专业问题：\n1. 你独立负责过最复杂的工作是什么？\n2. 遇到过最棘手的问题是什么？怎么解决的？\n3. 你觉得自己最擅长什么？最不擅长什么？\n4. 怎么提升工作效率？有什么方法？\n\n二、行业验证问题：\n1. 汽车/出行服务行业里哪家公司做得比较好？\n2. 这个岗位在行业里工资大概多少？\n3. 你觉得这个行业最大的特点是什么？\n4. 你平时怎么提升自己？",
