        "approval": "【岗位核心能力】专业技能、独立工作能力、问题解决、责任心、学习能力、团队协作。\n\n【行业适配性】是否有生活服务/服务业行业经验、专业技能是否匹配、稳定性如何、能否独当一面。\n\n【风险提示】中级岗位是跳槽主力，需要核实真实水平；很多人\"什么都知道一点但都不深\"；要考察是\"熟练工\"还是\"有思想的\"。"
