        "interview": "一、岗位专业问题：\n1. 你带过多大的团队？怎么分工和管理的？\n2. 怎么制定团队目标？怎么确保完成？\n3. 怎么招人？怎么判断人行不行？\n4. 团队有矛盾怎么办？怎么处理？\n\n二、行业验证问题：\n1. 通用职能/跨行业岗位库行业的管理有什么特点？\n2. 行业内哪家公司管理做得好？\n3. 管理岗的薪资大概是什么水平？\n4. 你觉得管理最难的是什么？",
